hierarchy.source:
(
  /* Запоминаем ссылки на контексты и объекты */
  $CONTEXTS := contexts;
  $COMPONENTS := components;
  /* Определяем фильтр для выделяемой иерархической структуры */
  $FILTER := $params.component;
  $FILTER_LN := $length($FILTER);
  /* Определяем иерархию владельцев */
  $PARENTS := $FILTER.$split(".")~>$map(function($v, $LIMIT, $a){(
      $a~>$map(function($v, $i) { $i <= $LIMIT ? $v})~>$join(".");
  )});
  $merge((
      /* Выбираем их компонентов нужные для построения диаграммы */
      [components.$spread().(
            $ID := $keys()[0];
            $PREFIX := $substring($ID, 0, $FILTER_LN + 1);
            $FILTER_LN = 0
            or ($PREFIX = $FILTER) or ($PREFIX = ($FILTER & "."))
            or ($ID in $PARENTS) ? $ID;
        )]
      ).(
        /* Готовим полный массив идентификаторов */
        ($~>$split(".")~>$map(function($v, $limit, $struct) {
          {
            $struct~>$map(function($pice, $index) {
              $index <= $limit ? $pice
            })~>$join("."): true
          }
        }))
    )
  ).$spread().(
    /* Готовим массив для вывода */
    $ID := $keys()[0];
    $CONTEXT := $lookup($CONTEXTS, $ID);
    $COMPONENT := $lookup($COMPONENTS, $ID);
    {
      "id": $ID,
      "title": $COMPONENT.title ? $COMPONENT.title : (
        $CONTEXT.title ? $CONTEXT.title : $reverse($split($ID, "."))[0]
      ),
      "link": $CONTEXT ? "/architect/contexts/" & $ID : "/architect/components/" & $ID
    }            
  )^(id).(
    /* Готовим PlantUML код для MindMap */
    $color := id = $FILTER ? "[#FFBBCC]" : "";
    "*" & $join($split(id, ".").("*")) & $color & " [[" & link & " " & title & "]]"
  )~>$join("\n");
)

tree.source:
(
  $COMPONENTS := components;
  $merge((
      /* Выбираем из компонентов нужные для построения диаграммы */
      [$COMPONENTS.$spread().(
          $keys()[0]~>$split(".")~>$map(function($v, $limit, $struct) {
              {
              $struct~>$map(function($pice, $index) {
                  $index <= $limit ? $pice
              })~>$join("."): true
              }
          })
      )]
    )
  ).$spread().(
    /* Готовим массив для вывода */
    $ID := $keys()[0];
    $COMPONENT := $lookup($COMPONENTS, $ID);
    {
      "id": $ID,
      "title": $COMPONENT.title ? $COMPONENT.title : $ID,
      "link": "/entities/components/blank?dh-component-id=" & $ID
    }            
  )^(id).(
    /* Готовим PlantUML код для MindMap */
    $content := " [[" & link & " " & title & "]]";
    "*" & $join($split(id, ".").("*")) & $content
  )~>$join("\n");
)

component.symbol:
(
  /* Обрабатываем входящие параметры */
  $manifest := $;
  $component := $params.subject.$spread()[0].*;
  $defConfig := $manifest.entities.contexts.config;

  /* Высота строки аспекта */
  $rowHeight := 14;
  /* Отступы */
  $padding := 8;
  /* Отступы */
  $headerOffset := 12;
  /* Ширину символа */
  $fontWidth := 7;
  /* Высота символа */
  $fontHeight := 12;

  /* Определяем заголовок */
  $header := $component.title;

  /* Определяем количество аспектов для вычисления высоты символа */
  $aspectCount := $count($component.aspects);

  /* Формируем массив аспектов */
  $aspects := $component.aspects.(
    $aspect := $lookup($manifest.aspects, $);
    {
      "id" : $,
      "title": $aspect.title ? $aspect.title : $ 
    }
  );

  /* Определяем максимальную длину текста для вычисления ширины символа */
  $maxTitle := $max([$max($aspects.($length(title))), $length($header)]);

  /* Вычисляем размеры символа */
  $width := $maxTitle ? $maxTitle * $fontWidth + $padding * 2 : 64; /* Умножаем на ширину символа */   
  $height := ($aspectCount + 1) * $rowHeight + $padding * 2 + $headerOffset; /* Умножаем на высоту строки */

  /* Генерируем символ */
  '<svg fill="#000000" width="' & $width & 'px" height="' & $height & 'px" viewBox="0 0 ' & $width & ' ' & $height & '" version="1.1" xmlns="http://www.w3.org/2000/svg">' 
        & '<g>'
            /* Создаем контейнер */
            & '<rect width="' & $width & 'px" height="' & $height & 'px" fill=\"#eee\" stroke=\"#222\" rx="3" />'
            /* Создаем заголовок */
            & '<text x="50%" y="12" style="font-size:' & $fontHeight & '" fill="green" text-anchor="middle" dominant-baseline="middle" >' & $header & '</text>'
            /* Заполняем аспектами */
            & $join($map($aspects, function($v, $i) {(
                '<a href=\"/architect/aspects/' & $v.id & '\" >'
                & '<text x="6" y="' & ($i * $rowHeight + $padding + $rowHeight + $headerOffset) & '" style="font-size:' & $fontHeight & '" fill="blue">' & $v.title & '</text>'
                & '</a>'
            )}))
        & '</g>'
  & '</svg>';
)
